insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('5bc30a8e-88c4-4443-b16a-d4b898d8f006', 'N2', 'N ＋ からすると／からすれば／からしたら', 'Đứng từ (vị trí)...mà nói thì.../Nhìn từ (cơ sở)...mà nói thì... (suy đoán/nhận định dựa trên góc nhìn)', NULL, 'N ＋ からすると／からすれば／からしたら', 'Đưa ra suy đoán/nhận định dựa trên góc nhìn/cơ sở của 1 đối tượng cụ thể', NULL, NULL, NULL, '{}', NULL, 70, 'N ＋ からすると／からすれば／からしたら', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('8b60dbe9-46cb-43ec-8363-d1006d8ac8f9', 'N2', 'N ＋ からして', 'Xét từ góc độ, xét về mặt.../Ngay cả, ngay từ... (dẫn chứng 1 điểm để suy ra kết luận chung)', NULL, 'N ＋ からして', 'Nêu 1 điểm cụ thể làm bằng chứng để suy ra 1 kết luận chung/tổng quát hơn', NULL, NULL, NULL, '{}', NULL, 70, 'N ＋ からして', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('bbaea93b-dee8-47af-b8e5-5d2283487e7b', 'N2', '普通形 ＋ とは', 'Thì thật là... (cảm thán bất ngờ trước 1 sự việc)', NULL, '普通形 ＋ とは', 'Diễn tả sự bất ngờ/ngạc nhiên mạnh mẽ của người nói trước 1 sự việc', NULL, NULL, NULL, '{}', NULL, 70, '普通形 ＋ とは', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('0ed3607a-2caf-4f96-b8ac-ee9c130da735', 'N2', 'N1(や・とか)N2... ＋ といったN', 'Ví dụ như.../Chẳng hạn như... (liệt kê ví dụ tiêu biểu rồi khái quát lại)', NULL, 'N1(や・とか)N2... ＋ といったN', 'Liệt kê 1 vài ví dụ tiêu biểu rồi khái quát lại bằng 1 danh từ chung', NULL, NULL, NULL, '{}', NULL, 70, 'N1(や・とか)N2... ＋ といったN', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('d1bb3115-f28e-4d2b-8af5-d230e8236969', 'N2', '普通形 ＋ としても', 'Cho dù là.../Thậm chí nếu là... (giả định điều kiện rồi khẳng định vế sau vẫn không đổi)', NULL, '普通形 ＋ としても', 'Đưa ra 1 giả định (thậm chí là giả định thái quá) rồi khẳng định kết luận vế sau vẫn không thay đổi', NULL, NULL, NULL, '{}', NULL, 70, '普通形 ＋ としても', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('0c0e3904-2d47-48c8-bac0-5bc54b302ffa', 'N2', 'Vる／N／Aい／Aな／Nである ＋ とともに', '① Cùng với (đồng hành cùng ai/cái gì)　② Càng...càng... (2 sự việc biến đổi song song)　③ ...đồng thời thì... (2 hành động/trạng thái xảy ra cùng lúc)', NULL, NULL, NULL, NULL, NULL, NULL, '{}', NULL, 70, 'Vる／N／Aい／Aな／Nである ＋ とともに', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('c1e48816-a11b-4392-81ff-18cda6e45fe1', 'N2', '普通形 ＋ としたら', 'Giả sử nếu mà.../Giả dụ như... (giả định 1 tình huống rồi nêu hành động/mong muốn)', NULL, '普通形 ＋ としたら', 'Đưa ra 1 giả định về tình huống, sau đó nêu hành động/mong muốn nếu giả định đó xảy ra', NULL, NULL, NULL, '{}', NULL, 70, '普通形 ＋ としたら', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('1e3dfc97-0181-47bf-8c3e-8428c074e5e7', 'N2', 'N ＋ といったら', 'Nói về... (nhấn mạnh cảm thán về 1 chủ đề)', NULL, 'N ＋ といったら', 'Đưa ra chủ đề rồi nhấn mạnh cảm thán mạnh mẽ về mức độ của chủ đề đó', NULL, NULL, NULL, '{}', NULL, 70, 'N ＋ といったら', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('f16b9dee-cb92-42b8-b9c0-72f292d243e5', 'N2', '普通形 ＋ ということだ', 'Có nghĩa là, tóm lại là, tức là... (kết luận/diễn giải lại ý nghĩa của 1 sự việc)', NULL, '普通形 ＋ ということだ', 'Diễn giải/kết luận lại ý nghĩa thực sự đằng sau 1 sự việc/hiện tượng đã nêu', NULL, NULL, NULL, '{}', NULL, 70, '普通形 ＋ ということだ', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('bebbbc6e-3dbf-4b7e-96bb-eafc2a166b03', 'N2', 'V(普)／Aい／Aな ＋ のなんのって', 'Cực kì, rất... (nhấn mạnh cảm thán mạnh mẽ, khẩu ngữ)', NULL, 'V(普)／Aい／Aな ＋ のなんのって', 'Nhấn mạnh cảm thán rất mạnh về mức độ của 1 tính chất/trạng thái, mang tính khẩu ngữ', NULL, NULL, NULL, '{}', NULL, 70, 'V(普)／Aい／Aな ＋ のなんのって', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('9ed41087-bf0e-436c-b98c-c84a868b14a3', 'N2', 'V(普)／Aいさ／み+の／Aな／Nの ＋ あまり', 'Vì quá... (mức độ quá mức của 1 trạng thái/cảm xúc dẫn đến kết quả nào đó)', NULL, 'V(普)／Aいさ／み+の／Aな／Nの ＋ あまり', 'Diễn tả 1 kết quả xảy ra do mức độ quá mức của 1 trạng thái/cảm xúc', NULL, NULL, NULL, '{}', NULL, 70, 'V(普)／Aいさ／み+の／Aな／Nの ＋ あまり', 'pdf', 'ok')
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('26dee72b-cf4e-472d-b354-a11939bc7540', '0c0e3904-2d47-48c8-bac0-5bc54b302ffa', 1, 'Cùng với (đồng hành/thực hiện cùng đối tượng đã nêu)', 'N ＋ とともに', 'Diễn tả hành động được thực hiện cùng với 1 người/đối tượng khác', NULL, 70, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('3527bb0b-83ac-46c8-8d49-91d0ff734482', '0c0e3904-2d47-48c8-bac0-5bc54b302ffa', 2, 'Càng...càng... (2 sự việc/hiện tượng biến đổi song song theo cùng chiều hướng)', 'Vる／N ＋ とともに', 'Diễn tả 2 sự việc cùng thay đổi song song với nhau theo cùng 1 chiều hướng', NULL, 70, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('24fd36fa-cbdc-4d09-afc9-087dd8de0683', '0c0e3904-2d47-48c8-bac0-5bc54b302ffa', 3, '...đồng thời thì... (2 hành động/trạng thái xảy ra cùng lúc, không nhất thiết biến đổi song song)', 'Vる ＋ とともに', 'Diễn tả 2 hành động/sự việc xảy ra đồng thời với nhau', NULL, 70, 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('5bc30a8e-88c4-4443-b16a-d4b898d8f006', NULL, 1, 'standard', '彼の日本語の発音からすると、韓国人だと推測している。', 'Xét từ cách phát âm tiếng Nhật của anh ấy, tôi đoán anh ấy là người Hàn Quốc.', '彼の日本語の発音＿＿＿、韓国人だと推測している。', 'からすると', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('5bc30a8e-88c4-4443-b16a-d4b898d8f006', NULL, 2, 'daily', '子供の立場からすれば、親の言葉は絶対的だ。', 'Đứng từ vị trí của trẻ con thì lời của cha mẹ là tuyệt đối.', '子供の立場＿＿＿、親の言葉は絶対的だ。', 'からすれば', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('5bc30a8e-88c4-4443-b16a-d4b898d8f006', NULL, 3, 'daily', '今の状況からしたら、計画の変更は避けられない。', 'Nhìn từ tình hình hiện tại thì việc thay đổi kế hoạch là không thể tránh khỏi.', '今の状況＿＿＿、計画の変更は避けられない。', 'からしたら', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('8b60dbe9-46cb-43ec-8363-d1006d8ac8f9', NULL, 1, 'standard', '雰囲気からして、彼女はただ者じゃないぞ。', 'Xét từ phong thái, cô ấy không phải là người bình thường đâu.', '雰囲気＿＿＿、彼女はただ者じゃないぞ。', 'からして', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('8b60dbe9-46cb-43ec-8363-d1006d8ac8f9', NULL, 2, 'daily', '名前からして、この店は高そうだ。', 'Ngay từ cái tên, cửa hàng này có vẻ đắt tiền.', '名前＿＿＿、この店は高そうだ。', 'からして', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('8b60dbe9-46cb-43ec-8363-d1006d8ac8f9', NULL, 3, 'daily', '態度からして、彼はやる気がなさそうだ。', 'Xét từ thái độ, có vẻ anh ấy không có hứng thú.', '態度＿＿＿、彼はやる気がなさそうだ。', 'からして', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('bbaea93b-dee8-47af-b8e5-5d2283487e7b', NULL, 1, 'standard', 'まさか私の犬がその人の手にかみついたとは、信じられなかった。', 'Không ngờ con chó của tôi lại cắn vào tay của người đó, thật khó tin.', 'まさか私の犬がその人の手にかみついた＿＿＿、信じられなかった。', 'とは', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('bbaea93b-dee8-47af-b8e5-5d2283487e7b', NULL, 2, 'daily', '彼が試験に落ちたとは驚いた。', 'Anh ấy trượt kỳ thi thì thật là bất ngờ.', '彼が試験に落ちた＿＿＿驚いた。', 'とは', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('bbaea93b-dee8-47af-b8e5-5d2283487e7b', NULL, 3, 'daily', 'こんなに早く結果が出るとは思わなかった。', 'Tôi không nghĩ là kết quả lại ra nhanh đến vậy.', 'こんなに早く結果が出る＿＿＿思わなかった。', 'とは', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0ed3607a-2caf-4f96-b8ac-ee9c130da735', NULL, 1, 'standard', '焼肉や牛丼といったお肉料理が大好きだ。', 'Tôi rất thích đồ ăn có thịt như là thịt nướng hay cơm thịt bò.', '焼肉や牛丼＿＿＿お肉料理が大好きだ。', 'といった', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0ed3607a-2caf-4f96-b8ac-ee9c130da735', NULL, 2, 'daily', '東京や大阪といった大都市に人口が集中している。', 'Dân số đang tập trung ở các thành phố lớn như Tokyo hay Osaka.', '東京や大阪＿＿＿大都市に人口が集中している。', 'といった', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0ed3607a-2caf-4f96-b8ac-ee9c130da735', NULL, 3, 'daily', '英語やフランス語といった外国語を学びたい。', 'Tôi muốn học các ngoại ngữ như tiếng Anh hay tiếng Pháp.', '英語やフランス語＿＿＿外国語を学びたい。', 'といった', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('d1bb3115-f28e-4d2b-8af5-d230e8236969', NULL, 1, 'standard', 'たとえきれいだとしても、性格が悪ければ付き合おうとは思わない。', 'Dù cho có xinh đẹp đi chăng nữa, nếu tính cách xấu thì tôi cũng không muốn hẹn hò.', 'たとえきれいだ＿＿＿、性格が悪ければ付き合おうとは思わない。', 'としても', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('d1bb3115-f28e-4d2b-8af5-d230e8236969', NULL, 2, 'daily', '今から急いだとしても、間に合わないだろう。', 'Cho dù có vội bây giờ đi nữa thì cũng không kịp đâu.', '今から急いだ＿＿＿、間に合わないだろう。', 'としても', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('d1bb3115-f28e-4d2b-8af5-d230e8236969', NULL, 3, 'daily', 'お金があったとしても、時間がなければ旅行はできない。', 'Cho dù có tiền đi nữa mà không có thời gian thì cũng không thể đi du lịch.', 'お金があった＿＿＿、時間がなければ旅行はできない。', 'としても', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0c0e3904-2d47-48c8-bac0-5bc54b302ffa', '26dee72b-cf4e-472d-b354-a11939bc7540', 1, 'standard', '友人とともに、沖縄旅行に行く予定を立てる。', 'Tôi đã lên kế hoạch đi du lịch Okinawa cùng với bạn thân.', '友人＿＿＿、沖縄旅行に行く予定を立てる。', 'とともに', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0c0e3904-2d47-48c8-bac0-5bc54b302ffa', '26dee72b-cf4e-472d-b354-a11939bc7540', 2, 'daily', '家族とともに、新年を迎えた。', 'Tôi đã đón năm mới cùng gia đình.', '家族＿＿＿、新年を迎えた。', 'とともに', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0c0e3904-2d47-48c8-bac0-5bc54b302ffa', '26dee72b-cf4e-472d-b354-a11939bc7540', 3, 'daily', '同僚とともに、プロジェクトを進めている。', 'Tôi đang tiến hành dự án cùng với đồng nghiệp.', '同僚＿＿＿、プロジェクトを進めている。', 'とともに', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0c0e3904-2d47-48c8-bac0-5bc54b302ffa', '3527bb0b-83ac-46c8-8d49-91d0ff734482', 1, 'standard', '季節の変化とともに木の葉の色も変わる。', 'Cùng với sự thay đổi của thời tiết thì màu lá cây cũng đổi màu theo.', '季節の変化＿＿＿木の葉の色も変わる。', 'とともに', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0c0e3904-2d47-48c8-bac0-5bc54b302ffa', '3527bb0b-83ac-46c8-8d49-91d0ff734482', 2, 'daily', '年を取るとともに、体力も衰えていく。', 'Cùng với việc lớn tuổi dần, thể lực cũng suy giảm theo.', '年を取る＿＿＿、体力も衰えていく。', 'とともに', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0c0e3904-2d47-48c8-bac0-5bc54b302ffa', '3527bb0b-83ac-46c8-8d49-91d0ff734482', 3, 'daily', '経済が発展するとともに、生活水準も上がる。', 'Cùng với sự phát triển kinh tế, mức sống cũng tăng theo.', '経済が発展する＿＿＿、生活水準も上がる。', 'とともに', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0c0e3904-2d47-48c8-bac0-5bc54b302ffa', '24fd36fa-cbdc-4d09-afc9-087dd8de0683', 1, 'standard', 'トムさんに英語の文法を教えてもらうとともに、発音の練習も一緒に行った。', 'Tôi vừa được anh Tom dạy cho ngữ pháp tiếng Anh đồng thời cũng luyện tập phát âm.', 'トムさんに英語の文法を教えてもらう＿＿＿、発音の練習も一緒に行った。', 'とともに', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0c0e3904-2d47-48c8-bac0-5bc54b302ffa', '24fd36fa-cbdc-4d09-afc9-087dd8de0683', 2, 'daily', '彼は医者であるとともに、大学の教授でもある。', 'Anh ấy vừa là bác sĩ, đồng thời cũng là giáo sư đại học.', '彼は医者である＿＿＿、大学の教授でもある。', 'とともに', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('0c0e3904-2d47-48c8-bac0-5bc54b302ffa', '24fd36fa-cbdc-4d09-afc9-087dd8de0683', 3, 'daily', '卒業するとともに、新しい生活が始まる。', 'Tốt nghiệp đồng thời cũng là lúc cuộc sống mới bắt đầu.', '卒業する＿＿＿、新しい生活が始まる。', 'とともに', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('c1e48816-a11b-4392-81ff-18cda6e45fe1', NULL, 1, 'standard', '宝くじが当たったとしたら、家族に海外旅行をプレゼントしたい。', 'Nếu như trúng xổ số, tôi muốn dành cho gia đình một chuyến du lịch nước ngoài.', '宝くじが当たった＿＿＿、家族に海外旅行をプレゼントしたい。', 'としたら', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('c1e48816-a11b-4392-81ff-18cda6e45fe1', NULL, 2, 'daily', 'もし生まれ変わるとしたら、鳥になりたい。', 'Nếu như được tái sinh, tôi muốn trở thành một con chim.', 'もし生まれ変わる＿＿＿、鳥になりたい。', 'としたら', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('c1e48816-a11b-4392-81ff-18cda6e45fe1', NULL, 3, 'daily', '時間があるとしたら、何をしたいですか。', 'Giả sử có thời gian thì bạn muốn làm gì?', '時間がある＿＿＿、何をしたいですか。', 'としたら', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('1e3dfc97-0181-47bf-8c3e-8428c074e5e7', NULL, 1, 'standard', '山の頂上からの景色といったら、美しすぎて言葉にならないくらいだ。', 'Nếu mà nói về phong cảnh từ đỉnh núi ngắm xuống, thì nó đẹp đến mức không nói nên lời.', '山の頂上からの景色＿＿＿、美しすぎて言葉にならないくらいだ。', 'といったら', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('1e3dfc97-0181-47bf-8c3e-8428c074e5e7', NULL, 2, 'daily', 'あの時の恥ずかしさといったら、忘れられない。', 'Nói về sự xấu hổ lúc đó thì không thể nào quên được.', 'あの時の恥ずかしさ＿＿＿、忘れられない。', 'といったら', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('1e3dfc97-0181-47bf-8c3e-8428c074e5e7', NULL, 3, 'daily', '彼の料理のおいしさといったら、他に類がない。', 'Nói về độ ngon món ăn của anh ấy thì không có gì sánh bằng.', '彼の料理のおいしさ＿＿＿、他に類がない。', 'といったら', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f16b9dee-cb92-42b8-b9c0-72f292d243e5', NULL, 1, 'standard', '彼は昨日も今日も練習を休んでいる。最初からやる気がなかったということだ。', 'Cậu ấy hôm qua lẫn hôm nay đều nghỉ tập. Có nghĩa là ngay từ đầu cậu ấy không có hứng thú rồi.', '彼は昨日も今日も練習を休んでいる。最初からやる気がなかった＿＿＿。', 'ということだ', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f16b9dee-cb92-42b8-b9c0-72f292d243e5', NULL, 2, 'daily', '返事がないということは、興味がないということだ。', 'Không có hồi âm tức là không có hứng thú.', '返事がないということは、興味がない＿＿＿。', 'ということだ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f16b9dee-cb92-42b8-b9c0-72f292d243e5', NULL, 3, 'daily', '彼が来ないということは、忙しいということだ。', 'Anh ấy không đến tức là đang bận rồi.', '彼が来ないということは、忙しい＿＿＿。', 'ということだ', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('bebbbc6e-3dbf-4b7e-96bb-eafc2a166b03', NULL, 1, 'standard', '彼はアメリカに3年住んでいるが、英語が下手なのなんのって。', 'Anh ấy mặc dù ở Mỹ 3 năm rồi mà tiếng Anh quá là kém.', '彼はアメリカに3年住んでいるが、英語が下手な＿＿＿。', 'のなんのって', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('bebbbc6e-3dbf-4b7e-96bb-eafc2a166b03', NULL, 2, 'daily', 'あの店のラーメン、辛いのなんのって、涙が出るほどだった。', 'Mì ramen ở quán đó cay ơi là cay, cay đến mức phát khóc.', 'あの店のラーメン、辛い＿＿＿、涙が出るほどだった。', 'のなんのって', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('bebbbc6e-3dbf-4b7e-96bb-eafc2a166b03', NULL, 3, 'daily', '久しぶりに運動したら、疲れたのなんのって。', 'Lâu ngày mới vận động, mệt kinh khủng luôn.', '久しぶりに運動したら、疲れた＿＿＿。', 'のなんのって', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('9ed41087-bf0e-436c-b98c-c84a868b14a3', NULL, 1, 'standard', '忙しさのあまり、食事をすることを忘れてしまっていた。', 'Vì quá bận nên tôi đã quên cả việc ăn.', '忙しさ＿＿＿、食事をすることを忘れてしまっていた。', 'のあまり', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('9ed41087-bf0e-436c-b98c-c84a868b14a3', NULL, 2, 'daily', '嬉しさのあまり、涙が出てしまった。', 'Vì quá vui nên tôi đã bật khóc.', '嬉しさ＿＿＿、涙が出てしまった。', 'のあまり', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('9ed41087-bf0e-436c-b98c-c84a868b14a3', NULL, 3, 'daily', '緊張のあまり、頭が真っ白になった。', 'Vì quá căng thẳng nên đầu óc tôi trở nên trống rỗng.', '緊張＿＿＿、頭が真っ白になった。', 'のあまり', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, correct_answer, source_type) values ('5bc30a8e-88c4-4443-b16a-d4b898d8f006', NULL, 'fill_blank', 'Điền vào chỗ trống: 彼の日本語の発音＿＿＿、韓国人だと推測している。', 'からすると', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('5bc30a8e-88c4-4443-b16a-d4b898d8f006', NULL, 'choose_meaning', 'Mẫu ngữ pháp "N ＋ からすると／からすれば／からしたら" (usage này) có nghĩa là gì?', 'Đứng từ (vị trí)...mà nói thì.../Nhìn từ (cơ sở)...mà nói thì... (suy đoán/nhận định dựa trên góc nhìn)', 'Nói về... (nhấn mạnh cảm thán về 1 chủ đề)', 'Vì quá... (mức độ quá mức của 1 trạng thái/cảm xúc dẫn đến kết quả nào đó)', 'Xét từ góc độ, xét về mặt.../Ngay cả, ngay từ... (dẫn chứng 1 điểm để suy ra kết luận chung)', 'Đứng từ (vị trí)...mà nói thì.../Nhìn từ (cơ sở)...mà nói thì... (suy đoán/nhận định dựa trên góc nhìn)', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('5bc30a8e-88c4-4443-b16a-d4b898d8f006', NULL, 'choose_connection', 'Cách nối nào tạo ra nghĩa: "Đứng từ (vị trí)...mà nói thì.../Nhìn từ (cơ sở)...mà nói thì... (suy đoán/nhận định dựa trên góc nhìn)"?', 'N ＋ からすると／からすれば／からしたら', 'N1(や・とか)N2... ＋ といったN', '普通形 ＋ とは', '普通形 ＋ ということだ', 'N ＋ からすると／からすれば／からしたら', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, correct_answer, source_type) values ('8b60dbe9-46cb-43ec-8363-d1006d8ac8f9', NULL, 'fill_blank', 'Điền vào chỗ trống: 雰囲気＿＿＿、彼女はただ者じゃないぞ。', 'からして', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('8b60dbe9-46cb-43ec-8363-d1006d8ac8f9', NULL, 'choose_meaning', 'Mẫu ngữ pháp "N ＋ からして" (usage này) có nghĩa là gì?', 'Ví dụ như.../Chẳng hạn như... (liệt kê ví dụ tiêu biểu rồi khái quát lại)', 'Đứng từ (vị trí)...mà nói thì.../Nhìn từ (cơ sở)...mà nói thì... (suy đoán/nhận định dựa trên góc nhìn)', 'Cực kì, rất... (nhấn mạnh cảm thán mạnh mẽ, khẩu ngữ)', 'Xét từ góc độ, xét về mặt.../Ngay cả, ngay từ... (dẫn chứng 1 điểm để suy ra kết luận chung)', 'Xét từ góc độ, xét về mặt.../Ngay cả, ngay từ... (dẫn chứng 1 điểm để suy ra kết luận chung)', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('8b60dbe9-46cb-43ec-8363-d1006d8ac8f9', NULL, 'choose_connection', 'Cách nối nào tạo ra nghĩa: "Xét từ góc độ, xét về mặt.../Ngay cả, ngay từ... (dẫn chứng 1 điểm để suy ra kết luận chung)"?', '普通形 ＋ としたら', 'N ＋ からして', 'N ＋ といったら', '普通形 ＋ としても', 'N ＋ からして', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, correct_answer, source_type) values ('bbaea93b-dee8-47af-b8e5-5d2283487e7b', NULL, 'fill_blank', 'Điền vào chỗ trống: まさか私の犬がその人の手にかみついた＿＿＿、信じられなかった。', 'とは', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('bbaea93b-dee8-47af-b8e5-5d2283487e7b', NULL, 'choose_meaning', 'Mẫu ngữ pháp "普通形 ＋ とは" (usage này) có nghĩa là gì?', 'Cho dù là.../Thậm chí nếu là... (giả định điều kiện rồi khẳng định vế sau vẫn không đổi)', 'Thì thật là... (cảm thán bất ngờ trước 1 sự việc)', 'Giả sử nếu mà.../Giả dụ như... (giả định 1 tình huống rồi nêu hành động/mong muốn)', '① Cùng với (đồng hành cùng ai/cái gì)　② Càng...càng... (2 sự việc biến đổi song song)　③ ...đồng thời thì... (2 hành động/trạng thái xảy ra cùng lúc)', 'Thì thật là... (cảm thán bất ngờ trước 1 sự việc)', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('bbaea93b-dee8-47af-b8e5-5d2283487e7b', NULL, 'choose_connection', 'Cách nối nào tạo ra nghĩa: "Thì thật là... (cảm thán bất ngờ trước 1 sự việc)"?', '普通形 ＋ ということだ', '普通形 ＋ とは', 'N ＋ といったら', 'N ＋ からして', '普通形 ＋ とは', 'generated');
