insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('0ed3607a-2caf-4f96-b8ac-ee9c130da735', NULL, 'choose_connection', 'Cách nối nào tạo ra nghĩa: "Ví dụ như.../Chẳng hạn như... (liệt kê ví dụ tiêu biểu rồi khái quát lại)"?', '普通形 ＋ ということだ', 'N ＋ といったら', 'N1(や・とか)N2... ＋ といったN', '普通形 ＋ としたら', 'N1(や・とか)N2... ＋ といったN', 'generated');
